use crate::aap::caps::state_read;

struct Node;

impl Guest for Node {
    // Keep only items whose id is not yet in the "seen" store. The id is a
    // parser-computed digest, so it is safe to use as a key; the untrusted
    // text fields are passed through unread.
    fn run(items: Vec<FeedItem>) -> Vec<FeedItem> {
        items
            .into_iter()
            .filter(|item| state_read::get(&item.id).is_none())
            .collect()
    }
}

export!(Node);
